import type { Doc, DocPart, GroupDoc } from './types.ts';

export const text = (value: string): Doc => ({ kind: 'text', value });
export const line: Doc = { kind: 'line' }, softline: Doc = { kind: 'softline' }, hardline: Doc = { kind: 'hardline' }, breakParent: Doc = { kind: 'break_parent' };
export const suffix = (value: string): Doc => ({ kind: 'suffix', value });
export const ifBreak = (broken: string, flat: string): Doc => ({ kind: 'if_break', broken, flat });

export function cat(...values: DocPart[]): Doc {
  const parts: Doc[] = [];
  const append = (value: DocPart): void => {
    if (value === null || value === undefined) return;
    if (Array.isArray(value)) { value.forEach(append); return; }
    if (typeof value === 'string') { append(text(value)); return; }
    if (value.kind === 'concat') { value.parts.forEach(append); return; }
    if (value.kind === 'text') {
      if (value.value === '') return;
      const previous = parts.at(-1);
      if (previous !== undefined && previous.kind === 'text') {
        parts[parts.length - 1] = text(previous.value + value.value); return;
      }
    }
    parts.push(value);
  };
  values.forEach(append);
  return parts.length === 0 ? text('') : parts.length === 1 ? parts[0] : { kind: 'concat', parts };
}

export function forceBroken(document: Doc): boolean {
  if (document.kind === 'hardline' || document.kind === 'break_parent') return true;
  if (document.kind === 'concat') return document.parts.some(forceBroken);
  if ('child' in document) return forceBroken(document.child);
  return false;
}

export function group(...parts: DocPart[]): GroupDoc { const child = cat(...parts); return { kind: 'group', child, forced: forceBroken(child), mode: null }; }
export const nest = (indent: number, ...parts: DocPart[]): Doc => ({ kind: 'nest', indent, child: cat(...parts) });
export const align = (...parts: DocPart[]): Doc => ({ kind: 'align', child: cat(...parts) });

export function groups(document: Doc): GroupDoc[] {
  const result: GroupDoc[] = [];
  const visit = (node: Doc): void => {
    if (node.kind === 'group') result.push(node);
    if (node.kind === 'concat') node.parts.forEach(visit);
    else if ('child' in node) visit(node.child);
  };
  visit(document); return result;
}

import type { Token, Lexed } from './types.ts';
export class FormatError extends Error {
  line: number;
  column: number;
  constructor(line: number, column: number, message: string) { super(message); this.line = line; this.column = column; }
}

export const TYPES = new Set<string>(['int', 'float', 'bool', 'string', 'void']);
const KEYWORDS = new Set([...TYPES, 'if', 'else', 'while', 'for', 'return', 'break', 'continue', 'true', 'false', 'switch', 'case', 'default']);
const DOUBLE_SYMBOLS = new Set(['<=', '>=', '==', '!=', '&&', '||', '+=', '-=', '*=', '/=', '%=']);
const letter = (value: string | undefined): boolean => value !== undefined && /[A-Za-z_]/.test(value);
const digit = (value: string | undefined): boolean => value !== undefined && value >= '0' && value <= '9';

export function tokenize(lines: string[]): Lexed {
  const tokens: Token[] = [], comments: Token[] = [], records: Token[] = [];
  let previousLine = 0;
  const append = (kind: string, value: string, line: number, column: number, comment = false): void => {
    const record: Token = { kind, value, line, column, blank: Math.max(0, line - previousLine - 1),
      comment, index: -1, leading: [], trailing: [] };
    previousLine = line; records.push(record);
    if (comment) comments.push(record);
    else { record.index = tokens.length; record.leading = []; record.trailing = []; tokens.push(record); }
  };
  lines.forEach((source, lineIndex) => {
    let i = 0;
    while (i < source.length) {
      const start = i, line = lineIndex + 1, column = i + 1, character = source[i], pair = source.slice(i, i + 2);
      if (character === ' ') { i++; continue; }
      if (pair === '//') { append('line_comment', source.slice(i).replace(/ +$/, ''), line, column, true); break; }
      if (pair === '/*') {
        const end = source.indexOf('*/', i + 2);
        if (end < 0) throw new FormatError(line, column, 'unterminated comment');
        i = end + 2; append('block_comment', source.slice(start, i), line, column, true); continue;
      }
      if (letter(character)) {
        while (letter(source[i]) || digit(source[i])) i++;
        const value = source.slice(start, i);
        append(KEYWORDS.has(value) ? 'keyword' : 'identifier', value, line, column); continue;
      }
      if (digit(character)) {
        while (digit(source[i])) i++;
        if (source[i] === '.' && digit(source[i + 1])) { i++; while (digit(source[i])) i++; }
        append('number', source.slice(start, i), line, column); continue;
      }
      if (character === '"') {
        i++;
        while (i < source.length && source[i] !== '"') i += source[i] === '\\' ? 2 : 1;
        if (i >= source.length) throw new FormatError(line, column, 'unterminated string');
        i++; append('string', source.slice(start, i), line, column); continue;
      }
      if (DOUBLE_SYMBOLS.has(pair)) { append('symbol', pair, line, column); i += 2; continue; }
      if ('+-*/%<>=!()[]{},;.?:'.includes(character)) { append('symbol', character, line, column); i++; continue; }
      throw new FormatError(line, column, "unexpected character '" + character + "'");
    }
  });
  tokens.push({ kind: 'end', value: '', line: lines.length + 1, column: 1, blank: 0, index: tokens.length, leading: [], trailing: [] });
  return { tokens, comments, records };
}

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { FormatError, tokenize } from './lexer.ts';
import { Parser, children } from './parser.ts';
import { cat, line, softline, hardline, breakParent, suffix, ifBreak, group, nest, align, groups } from './doc_builder.ts';
import { layout } from './printer.ts';
import { documentLines, diff } from './report.ts';
import type {
  Token, Profile, Source, Lexed, Doc, DocPart, AstNode, ExprNode, ProgramNode,
  FunctionNode, ParameterNode, DeclarationNode, ListNode, BlockNode, StatementNode,
  SimpleNode, IfNode, WhileNode, ForNode, ClauseNode, SwitchNode, AssignmentNode,
  BinaryNode, ConditionalNode, PostfixNode, FormatResult,
} from './types.ts';

const inputLines = (name: string): string[] => readFileSync('input/' + name, 'ascii').split('\n').slice(0, -1);
const trimLines = (lines: string[]): string[] => lines.map(value => value.replace(/ +$/, ''));

function readProfiles(): Map<string,Profile> {
  const profiles = new Map<string,Profile>(), numeric = new Set(['width', 'indent', 'max_blank_lines', 'comment_column']);
  let current: Profile | null = null;
  for (const value of inputLines('style.txt')) {
    if (value === '') continue;
    if (value.startsWith('[')) { current = {} as Profile; profiles.set(value.slice(1, -1), current); }
    else {
      const [key, setting] = value.split('='); current![key] = numeric.has(key) ? Number(setting) : setting;
    }
  }
  return profiles;
}

function readSources(profiles: Map<string,Profile>): Source[] {
  const sources: Source[] = [];
  for (const value of inputLines('sources.txt')) {
    if (value.startsWith('=== ')) {
      const [, name, profile] = value.split(' ');
      sources.push({ header: value, name, profile: profiles.get(profile)!, lines: [] });
    } else sources[sources.length - 1].lines.push(value);
  }
  return sources;
}

function attachComments(lexed: Lexed): void {
  const { tokens, records } = lexed;
  const following: (Token | null)[] = Array(records.length), end = tokens[tokens.length - 1];
  let next: Token | null = null;
  for (let i = records.length - 1; i >= 0; i--) {
    following[i] = next;
    if (!records[i].comment) next = records[i];
  }
  let previous: Token | null = null;
  for (let i = 0; i < records.length; i++) {
    const record = records[i];
    if (!record.comment) { previous = record; continue; }
    next = following[i];
    if (previous !== null && previous.line === record.line && (next === null || next.line > record.line)) {
      previous.trailing.push(record);
    } else {
      record.own = record.kind === 'line_comment' || i + 1 === records.length || records[i + 1].line > record.line;
      (next === null ? end : next).leading.push(record);
    }
  }
  for (const token of tokens) token.sourceTrailing = token.trailing.length > 0;
}

function checkComments(program: ProgramNode, tokens: Token[]): void {
  const allowed = new Set<Token>([program.end]), trailingCommas = new Set<Token>();
  const allowBody = (body: StatementNode): void => { if (body.kind !== 'block') allowed.add(body.first); };
  const work: AstNode[] = [program];
  while (work.length) {
    const node = work.pop()!;
    if (node.kind === 'program') node.items.forEach(item => allowed.add(item.first));
    if (node.kind === 'block') {
      allowed.add(node.close); node.statements.forEach(statement => allowed.add(statement.first));
    }
    if (node.kind === 'switch') {
      allowed.add(node.close);
      for (const clause of node.clauses) {
        allowed.add(clause.label); clause.statements.forEach(statement => allowed.add(statement.first));
      }
    }
    if (node.kind === 'if' || node.kind === 'while' || node.kind === 'for') allowBody(node.body);
    if (node.kind === 'if' && node.alternative !== null && node.alternative.kind !== 'if') allowBody(node.alternative);
    if (node.kind === 'list') {
      node.elements.forEach(element => allowed.add(element.first));
      if (node.trailing !== null) trailingCommas.add(node.trailing);
    }
    const nested = children(node);
    for (let i = nested.length - 1; i >= 0; i--) work.push(nested[i]);
  }
  for (const token of tokens) for (const comment of token.leading) {
    if (trailingCommas.has(token) || (comment.own && !allowed.has(token))) {
      throw new FormatError(comment.line, comment.column, 'comment not allowed here');
    }
  }
}

const expressionLevel = (expression: ExprNode): number => expression.kind === 'conditional' ? 0 : expression.kind === 'binary' ? expression.precedence : expression.kind === 'unary' ? 7 : 8;
const postfix = (expression: ExprNode): expression is PostfixNode => ['call', 'index', 'member'].includes(expression.kind);

class DocumentBuilder {
  profile: Profile;
  tokens: Token[];
  indent: number;
  space: string;
  keywordSpace: string;
  operatorBreak: Doc;
  firstFunction: {name:string; document: Doc} | null;
  constructor(profile: Profile, tokens: Token[]) {
    this.profile = profile; this.tokens = tokens; this.indent = profile.indent;
    this.space = profile.space_around_operators === 'yes' ? ' ' : '';
    this.keywordSpace = profile.space_after_keyword === 'yes' ? ' ' : '';
    this.operatorBreak = profile.space_around_operators === 'yes' ? line : softline;
    this.firstFunction = null;
  }

  separation(blank: number): Doc { return cat(Array(1 + Math.min(blank, this.profile.max_blank_lines)).fill(hardline)); }
  preBlank(token: Token): number { return token.leading.length ? token.leading[0].blank : token.blank; }

  comments(comments: Token[], final: Token | null): Doc {
    const parts: DocPart[] = [];
    comments.forEach((comment, i) => {
      parts.push(comment.value);
      const next = i + 1 < comments.length ? comments[i + 1] : final;
      if (next !== null) parts.push(comment.own ? this.separation(next.blank) : ' ');
    });
    return cat(parts);
  }

  trailing(token: Token): DocPart { return token.trailing.length ? suffix(token.trailing.map(comment => comment.value).join(' ')) : ''; }
  token(token: Token, leading: Token[] = token.leading): Doc { return cat(this.comments(leading, token), token.value, this.trailing(token)); }

  closingComments(token: Token): {own:Token[]; inline:Token[]} {
    let lastOwn = -1;
    token.leading.forEach((comment, i) => { if (comment.own) lastOwn = i; });
    return { own: token.leading.slice(0, lastOwn + 1), inline: token.leading.slice(lastOwn + 1) };
  }

  sequence<T extends AstNode & {first: Token}>(nodes: T[], render: (node: T) => DocPart): Doc {
    const parts: DocPart[] = [];
    nodes.forEach((node, i) => {
      if (i > 0) parts.push(this.separation(this.preBlank(node.first)));
      parts.push(render(node));
    });
    return cat(parts);
  }

  beforeClosing(comments: Token[], hasItems: boolean): DocPart {
    if (comments.length === 0) return '';
    return cat(hasItems ? this.separation(comments[0].blank) : '', this.comments(comments, null));
  }

  program(program: ProgramNode): Doc {
    const document = this.sequence(program.items, item => {
      const result = item.kind === 'function' ? this.function(item) : this.declaration(item);
      if (item.kind === 'function' && this.firstFunction === null) this.firstFunction = { name: item.name.value, document: result };
      return result;
    });
    return cat(document, this.beforeClosing(program.end.leading, program.items.length > 0));
  }

  function(node: FunctionNode): Doc {
    return cat(this.token(node.type), ' ', this.token(node.name), this.list(node.parameters), hardline, this.block(node.body));
  }

  parameter(node: ParameterNode): Doc {
    return cat(this.token(node.type), ' ', this.token(node.name), node.dimensions.map(dimension => cat(this.token(dimension.open), this.token(dimension.close))));
  }

  declaration(node: DeclarationNode): Doc {
    const parts: DocPart[] = [this.token(node.type), ' ', this.token(node.name)];
    for (const dimension of node.dimensions) {
      parts.push(this.token(dimension.open), dimension.value === null ? '' : this.expression(dimension.value, 0), this.token(dimension.close));
    }
    if (node.equal !== null) parts.push(this.space, this.token(node.equal), this.space, this.initializer(node.initializer!));
    if (node.semi !== null) parts.push(this.token(node.semi!));
    return cat(parts);
  }

  initializer(node: ExprNode | ListNode): DocPart { return node.kind === 'list' ? this.list(node) : this.expression(node, 0); }

  list(node: ListNode): Doc {
    if (node.elements.length === 0) return cat(this.token(node.open), this.token(node.close));
    const forced = this.tokens.slice(node.open.index, node.close.index).some(token => token.sourceTrailing);
    const parts: DocPart[] = [softline];
    node.elements.forEach((element, i) => {
      parts.push(node.role === 'parameters' ? this.parameter(element as ParameterNode) : node.role === 'initializers' ? this.initializer(element as ExprNode | ListNode) : this.expression(element as ExprNode, 0));
      if (i + 1 < node.elements.length) parts.push(this.token(node.commas[i]), line);
    });
    if (node.role === 'initializers') {
      parts.push(ifBreak(',', ''));
      if (node.trailing !== null) parts.push(this.trailing(node.trailing));
    }
    return group(forced ? breakParent : '', this.token(node.open), nest(this.indent, parts), softline, this.token(node.close));
  }

  block(node: BlockNode): Doc {
    const comments = this.closingComments(node.close);
    if (node.statements.length === 0 && comments.own.length === 0) return cat(this.token(node.open), this.token(node.close, comments.inline));
    return cat(this.token(node.open), nest(this.indent, hardline,
      this.sequence(node.statements, statement => this.statement(statement)), this.beforeClosing(comments.own, node.statements.length > 0)),
    hardline, this.token(node.close, comments.inline));
  }

  body(node: StatementNode): Doc {
    const beforeBrace = this.profile.brace_style === 'kr' ? ' ' : hardline;
    if (node.kind === 'block') return cat(beforeBrace, this.block(node));
    if (this.profile.add_braces === 'yes') return cat(beforeBrace, '{', nest(this.indent, hardline, this.statement(node)), hardline, '}');
    return nest(this.indent, hardline, this.statement(node));
  }

  simple(node: SimpleNode): Doc {
    return node.kind === 'assignment' ? cat(this.expression(node.left, 0), this.space, this.token(node.operator), this.space, this.expression(node.right, 0))
      : this.expression(node.value, 0);
  }

  ifStatement(node: IfNode): Doc {
    const parts = [this.token(node.keyword), this.keywordSpace, this.token(node.open), this.expression(node.condition, 0), this.token(node.close), this.body(node.body)];
    if (node.otherwise !== null) {
      const together = this.profile.brace_style === 'kr' && (node.body.kind === 'block' || this.profile.add_braces === 'yes');
      parts.push(together ? ' ' : hardline, this.token(node.otherwise!), node.alternative!.kind === 'if' ? cat(' ', this.ifStatement(node.alternative as IfNode)) : this.body(node.alternative!));
    }
    return cat(parts);
  }

  forStatement(node: ForNode): Doc {
    const initial = node.initial === null ? '' : node.initial.kind === 'declaration' ? this.declaration(node.initial) : this.simple(node.initial);
    const middle = group(align(initial, this.token(node.firstSemi), node.condition === null ? '' : cat(line, this.expression(node.condition, 0)),
      this.token(node.secondSemi), node.update === null ? '' : cat(line, this.simple(node.update))));
    return cat(this.token(node.keyword), this.keywordSpace, this.token(node.open), middle, this.token(node.close), this.body(node.body));
  }

  clause(node: ClauseNode): Doc {
    return cat(this.token(node.label), node.value === null ? '' : cat(' ', this.expression(node.value, 0)), this.token(node.colon),
      node.statements.length === 0 ? '' : nest(this.indent, hardline, this.sequence(node.statements, statement => this.statement(statement))));
  }

  switchStatement(node: SwitchNode): Doc {
    const comments = this.closingComments(node.close);
    const start = cat(this.token(node.keyword), this.keywordSpace, this.token(node.left), this.expression(node.condition, 0), this.token(node.right),
      this.profile.brace_style === 'kr' ? ' ' : hardline, this.token(node.open));
    if (node.clauses.length === 0 && comments.own.length === 0) return cat(start, this.token(node.close, comments.inline));
    const indent = this.profile.indent_case_labels === 'yes' ? this.indent : 0;
    return cat(start, nest(indent, hardline, this.sequence(node.clauses, clause => this.clause(clause)),
      this.beforeClosing(comments.own, node.clauses.length > 0)), hardline, this.token(node.close, comments.inline));
  }

  statement(node: StatementNode): Doc {
    switch (node.kind) {
      case 'block': return this.block(node);
      case 'declaration': return this.declaration(node);
      case 'assignment': case 'expression_statement': return cat(this.simple(node), this.token(node.semi!));
      case 'return': return cat(this.token(node.keyword), node.value === null ? '' : cat(' ', this.expression(node.value, 0)), this.token(node.semi));
      case 'jump': return cat(this.token(node.keyword), this.token(node.semi));
      case 'if': return this.ifStatement(node);
      case 'while': return cat(this.token(node.keyword), this.keywordSpace, this.token(node.open), this.expression(node.condition, 0), this.token(node.close), this.body(node.body));
      case 'for': return this.forStatement(node);
      case 'switch': return this.switchStatement(node);
    }
  }

  openAt(node: ExprNode, required: number): ExprNode {
    if (this.profile.remove_parens !== 'yes') return node;
    while (node.kind === 'parenthesized' && expressionLevel(node.inner) >= required && node.open.leading.length === 0 && node.close.leading.length === 0) {
      const inner = node.inner;
      inner.first.trailing = [...node.open.trailing, ...inner.first.trailing];
      inner.last.trailing = [...inner.last.trailing, ...node.close.trailing];
      node.open.trailing = []; node.close.trailing = []; node = inner;
    }
    return node;
  }

  binary(node: BinaryNode): Doc {
    const precedence = node.precedence, operations: {operator: Token; right: ExprNode}[] = [];
    let first = node;
    while (first.kind === 'binary' && first.precedence === precedence) {
      operations.push({ operator: first.operator, right: first.right }); first = this.openAt(first.left, precedence);
    }
    operations.reverse();
    const head = this.expression(first, precedence), tail: DocPart[] = [];
    for (const operation of operations) tail.push(this.operatorBreak, this.token(operation.operator), this.space, this.expression(operation.right, precedence + 1));
    return group(head, nest(this.indent, tail));
  }

  conditional(node: ConditionalNode): Doc {
    const tail: DocPart[] = [];
    let current = node;
    while (true) {
      tail.push(this.operatorBreak, this.token(current.question), this.space, this.expression(current.yes, 0), this.operatorBreak, this.token(current.colon), this.space);
      const next = this.openAt(current.no, 0);
      if (next.kind !== 'conditional') { tail.push(this.expression(next, 0)); break; }
      tail.push(this.expression(next.condition, 1)); current = next;
    }
    return group(this.expression(node.condition, 1), nest(this.indent, tail));
  }

  postfixPart(node: PostfixNode): Doc {
    if (node.kind === 'call') return this.list(node.argumentsList);
    if (node.kind === 'index') return cat(this.token(node.open), this.expression(node.value, 0), this.token(node.close));
    return cat(this.token(node.dot), this.token(node.name));
  }

  postfix(node: PostfixNode): Doc {
    const operations: PostfixNode[] = [];
    let head = node;
    while (postfix(head)) { operations.push(head); head = this.openAt(head.target, 8); }
    operations.reverse();
    const segments: PostfixNode[][] = [[]];
    for (const operation of operations) {
      if (operation.kind === 'member') segments.push([]);
      segments[segments.length - 1].push(operation);
    }
    const callSegments = segments.map((segment, index) => ({ index, call: index > 0 && segment.some(operation => operation.kind === 'call') })).filter(segment => segment.call);
    const first = this.expression(head, 8);
    if (callSegments.length < 2) return cat(first, operations.map(operation => this.postfixPart(operation)));
    const start = callSegments[0].index;
    const prefix = segments.slice(0, start).flatMap(segment => segment.map(operation => this.postfixPart(operation)));
    const tail = segments.slice(start).map(segment => cat(softline, segment.map(operation => this.postfixPart(operation))));
    return group(first, prefix, nest(this.indent, tail));
  }

  expression(node: ExprNode, required: number): Doc {
    node = this.openAt(node, required);
    switch (node.kind) {
      case 'primary': return this.token(node.token);
      case 'parenthesized': return cat(this.token(node.open), this.expression(node.inner, 0), this.token(node.close));
      case 'unary': return cat(this.token(node.operator), this.expression(node.operand, 8));
      case 'binary': return this.binary(node);
      case 'conditional': return this.conditional(node);
      case 'call': case 'index': case 'member': return this.postfix(node);
    }
  }
}

function formatSource(source: string[], profile: Profile): FormatResult {
  try {
    const lexed = tokenize(source); attachComments(lexed);
    const program = new Parser(lexed.tokens).program(); checkComments(program, lexed.tokens);
    const builder = new DocumentBuilder(profile, lexed.tokens), document = builder.program(program);
    const formatted = program.items.length === 0 && program.end.leading.length === 0 ? [] : layout(document, profile);
    const allGroups = groups(document);
    const metrics = { lines: formatted.length, longest: formatted.reduce((longest, line) => Math.max(longest, line.length), 0), comments: lexed.comments.length,
      groups: allGroups.length, broken: allGroups.filter(node => node.mode === 'break' || node.mode === 'forced').length,
      forced: allGroups.filter(node => node.mode === 'forced').length };
    return { formatted, metrics, firstFunction: builder.firstFunction };
  } catch (error) {
    if (!(error instanceof FormatError)) throw error;
    return { error, formatted: trimLines(source) };
  }
}

function idempotency(name: string, first: FormatResult, profile: Profile): string {
  const second = formatSource(first.formatted, profile);
  if (second.error) return `${name}: unstable (second pass: ${second.error.line}:${second.error.column}: ${second.error.message})`;
  for (let i = 0; i < Math.max(first.formatted.length, second.formatted.length); i++) {
    if (first.formatted[i] !== second.formatted[i]) return `${name}: unstable at line ${i + 1}`;
  }
  return name + ': stable';
}

function main(): void {
  const sources = readSources(readProfiles()), formatted: string[] = [], checks: string[] = [];
  const diagnostics: string[] = [], documents: string[] = [], changes: string[] = [];
  for (const source of sources) {
    const result = formatSource(source.lines, source.profile), name = source.name;
    formatted.push(source.header, ...result.formatted); documents.push('=== ' + name); changes.push('=== ' + name);
    if (result.error) {
      checks.push(name + ': skipped (syntax error)'); documents.push('syntax error'); changes.push('skipped (syntax error)');
      diagnostics.push(`${name}:${result.error.line}:${result.error.column}: error: ${result.error.message}`);
      continue;
    }
    checks.push(idempotency(name, result, source.profile));
    result.formatted.forEach((line, i) => {
      if (line.length > source.profile.width) diagnostics.push(`${name}:${i + 1}: warning: line too long (${line.length} > ${source.profile.width})`);
    });
    const metrics = result.metrics!;
    documents.push(`metrics lines=${metrics.lines} longest=${metrics.longest} comments=${metrics.comments} groups=${metrics.groups} broken=${metrics.broken} forced=${metrics.forced}`);
    if (result.firstFunction === null) documents.push('no function');
    else documents.push('function ' + result.firstFunction!.name, ...documentLines(result.firstFunction!.document));
    changes.push(...diff(trimLines(source.lines), result.formatted));
  }
  if (diagnostics.length === 0) diagnostics.push('no diagnostics');
  mkdirSync('output', { recursive: true });
  const outputs: [string,string[]][] = [['formatted.txt', formatted], ['idempotency.txt', checks], ['diagnostics.txt', diagnostics], ['doc_tree.txt', documents], ['changes.txt', changes]];
  for (const [name, lines] of outputs) writeFileSync('output/' + name, lines.join('\n') + '\n', 'ascii');
}

main();

import { FormatError, TYPES } from './lexer.ts';
import type {
  Token, AstNode, ProgramNode, ParameterNode, DeclarationNode, ListNode,
  BlockNode, StatementNode, SimpleNode, IfNode, ForNode, SwitchNode, ExprNode,
} from './types.ts';
const ASSIGNMENTS = new Set(['=', '+=', '-=', '*=', '/=', '%=']);
const PRECEDENCE = new Map([['||', 1], ['&&', 2], ['==', 3], ['!=', 3], ['<', 4], ['<=', 4], ['>', 4], ['>=', 4], ['+', 5], ['-', 5], ['*', 6], ['/', 6], ['%', 6]]);

export class Parser {
  tokens: Token[];
  position: number;
  constructor(tokens: Token[]) { this.tokens = tokens; this.position = 0; }
  peek(offset = 0): Token { return this.tokens[Math.min(this.position + offset, this.tokens.length - 1)]; }
  is(value: string): boolean { return this.peek().value === value; }
  fail(expected: string): never {
    const token = this.peek(), actual = token.kind === 'end' ? 'end of file' : "'" + token.value + "'";
    throw new FormatError(token.line, token.column, 'expected ' + expected + ', found ' + actual);
  }
  read(value: string): Token { if (!this.is(value)) this.fail("'" + value + "'"); return this.tokens[this.position++]; }
  identifier(): Token { if (this.peek().kind !== 'identifier') this.fail('identifier'); return this.tokens[this.position++]; }
  type(): Token { if (!TYPES.has(this.peek().value)) this.fail('type'); return this.tokens[this.position++]; }
  node<K extends AstNode['kind']>(kind: K, first: Token,
    fields: Omit<Extract<AstNode, {kind: K}>, 'kind'|'first'|'last'>): Extract<AstNode, {kind: K}> {
    return { kind, first, last: this.tokens[this.position - 1], ...fields } as Extract<AstNode, {kind: K}>;
  }
  program(): ProgramNode {
    const items: ProgramNode['items'] = [];
    while (this.peek().kind !== 'end') {
      const type = this.type(), name = this.identifier();
      if (this.is('(')) {
        const parameters = this.list('(', ')', 'parameters', false, () => this.parameter()), body = this.block();
        items.push(this.node('function', type, { type, name, parameters, body }));
      } else items.push(this.declaration(type, name, true));
    }
    return { kind: 'program', items, end: this.peek() };
  }
  parameter(): ParameterNode {
    const type = this.type(), name = this.identifier(), dimensions: ParameterNode['dimensions'] = [];
    while (this.is('[')) dimensions.push({ open: this.read('['), close: this.read(']') });
    return this.node('parameter', type, { type, name, dimensions });
  }
  declaration(type: Token, name: Token, semicolon: boolean): DeclarationNode {
    const dimensions: DeclarationNode['dimensions'] = [];
    while (this.is('[')) {
      const open = this.read('['), value = this.is(']') ? null : this.expression(), close = this.read(']');
      dimensions.push({ open, value, close });
    }
    let equal = null, initializer = null;
    if (this.is('=')) { equal = this.read('='); initializer = this.initializer(); }
    const semi = semicolon ? this.read(';') : null;
    return this.node('declaration', type, { type, name, dimensions, equal, initializer, semi });
  }
  initializer(): ExprNode | ListNode { return this.is('{') ? this.list('{', '}', 'initializers', true, () => this.initializer()) : this.expression(); }
  list(opening: string, closing: string, role: string, allowTrailing: boolean,
    element: () => ParameterNode | ExprNode | ListNode): ListNode {
    const open = this.read(opening), elements: ListNode['elements'] = [], commas: Token[] = [];
    let trailing = null;
    if (!this.is(closing)) {
      elements.push(element());
      while (this.is(',')) {
        if (allowTrailing && this.peek(1).value === closing) { trailing = this.read(','); break; }
        commas.push(this.read(',')); elements.push(element());
      }
    }
    const close = this.read(closing);
    return this.node('list', open, { open, close, role, elements, commas, trailing });
  }
  block(): BlockNode {
    const open = this.read('{'), statements: StatementNode[] = [];
    while (!this.is('}') && this.peek().kind !== 'end') statements.push(this.statement());
    const close = this.read('}');
    return this.node('block', open, { open, close, statements });
  }
  statement(): StatementNode {
    const first = this.peek();
    if (this.is('{')) return this.block();
    if (TYPES.has(first.value)) { const type = this.type(), name = this.identifier(); return this.declaration(type, name, true); }
    if (this.is('if')) return this.ifStatement();
    if (this.is('while')) {
      const keyword = this.read('while'), open = this.read('('), condition = this.expression(), close = this.read(')'), body = this.statement();
      return this.node('while', first, { keyword, open, condition, close, body });
    }
    if (this.is('for')) return this.forStatement();
    if (this.is('switch')) return this.switchStatement();
    if (this.is('return')) {
      const keyword = this.read('return'), value = this.is(';') ? null : this.expression(), semi = this.read(';');
      return this.node('return', first, { keyword, value, semi });
    }
    if (this.is('break') || this.is('continue')) {
      const keyword = this.read(first.value), semi = this.read(';');
      return this.node('jump', first, { keyword, semi });
    }
    const result = this.simple(); result.semi = this.read(';'); result.last = result.semi; return result;
  }
  ifStatement(): IfNode {
    const keyword = this.read('if'), open = this.read('('), condition = this.expression(), close = this.read(')'), body = this.statement();
    let otherwise = null, alternative = null;
    if (this.is('else')) { otherwise = this.read('else'); alternative = this.statement(); }
    return this.node('if', keyword, { keyword, open, condition, close, body, otherwise, alternative });
  }
  forStatement(): ForNode {
    const keyword = this.read('for'), open = this.read('(');
    let initial: ForNode['initial'] = null;
    if (!this.is(';')) {
      if (TYPES.has(this.peek().value)) { const type = this.type(), name = this.identifier(); initial = this.declaration(type, name, false); }
      else initial = this.simple();
    }
    const firstSemi = this.read(';'), condition = this.is(';') ? null : this.expression(), secondSemi = this.read(';');
    const update = this.is(')') ? null : this.simple(), close = this.read(')'), body = this.statement();
    return this.node('for', keyword, { keyword, open, initial, firstSemi, condition, secondSemi, update, close, body });
  }
  switchStatement(): SwitchNode {
    const keyword = this.read('switch'), left = this.read('('), condition = this.expression(), right = this.read(')'), open = this.read('{'), clauses: SwitchNode['clauses'] = [];
    while (this.is('case') || this.is('default')) {
      const label = this.read(this.peek().value), value = label.value === 'case' ? this.expression() : null, colon = this.read(':'), statements: StatementNode[] = [];
      while (!['case', 'default', '}'].includes(this.peek().value) && this.peek().kind !== 'end') statements.push(this.statement());
      clauses.push(this.node('clause', label, { label, value, colon, statements }));
    }
    const close = this.read('}');
    return this.node('switch', keyword, { keyword, left, condition, right, open, close, clauses });
  }
  simple(): SimpleNode {
    const left = this.expression();
    if (ASSIGNMENTS.has(this.peek().value)) {
      const operator = this.read(this.peek().value), right = this.expression();
      return this.node('assignment', left.first, { left, operator, right, semi: null });
    }
    return this.node('expression_statement', left.first, { value: left, semi: null });
  }
  expression(): ExprNode {
    const condition = this.binary(1);
    if (!this.is('?')) return condition;
    const question = this.read('?'), yes = this.expression(), colon = this.read(':'), no = this.expression();
    return this.node('conditional', condition.first, { condition, question, yes, colon, no });
  }
  binary(precedence: number): ExprNode {
    if (precedence === 7) return this.unary();
    let left = this.binary(precedence + 1);
    while (PRECEDENCE.get(this.peek().value) === precedence) {
      const operator = this.read(this.peek().value), right = this.binary(precedence + 1);
      left = this.node('binary', left.first, { left, operator, right, precedence });
    }
    return left;
  }
  unary(): ExprNode {
    if (this.is('-') || this.is('!')) {
      const operator = this.read(this.peek().value), operand = this.unary();
      return this.node('unary', operator, { operator, operand });
    }
    let target = this.primary();
    while (true) {
      if (this.is('(')) {
        const argumentsList = this.list('(', ')', 'arguments', false, () => this.expression());
        target = this.node('call', target.first, { target, argumentsList });
      } else if (this.is('[')) {
        const open = this.read('['), value = this.expression(), close = this.read(']');
        target = this.node('index', target.first, { target, open, value, close });
      } else if (this.is('.')) {
        const dot = this.read('.'), name = this.identifier(); target = this.node('member', target.first, { target, dot, name });
      } else return target;
    }
  }
  primary(): ExprNode {
    const token = this.peek();
    if (['identifier', 'number', 'string'].includes(token.kind) || token.value === 'true' || token.value === 'false') {
      this.position++; return this.node('primary', token, { token });
    }
    if (this.is('(')) {
      const open = this.read('('), inner = this.expression(), close = this.read(')');
      return this.node('parenthesized', open, { open, inner, close });
    }
    this.fail('expression');
  }
}

export function children(node: AstNode): AstNode[] {
  switch (node.kind) {
    case 'program': return node.items;
    case 'function': return [node.parameters, node.body];
    case 'declaration': return [...node.dimensions.map(dimension => dimension.value), node.initializer].filter((value): value is NonNullable<typeof value> => value !== null);
    case 'list': return node.elements;
    case 'block': return node.statements;
    case 'clause': return [node.value, ...node.statements].filter((value): value is NonNullable<typeof value> => value !== null);
    case 'if': return [node.condition, node.body, node.alternative].filter((value): value is NonNullable<typeof value> => value !== null);
    case 'while': return [node.condition, node.body];
    case 'for': return [node.initial, node.condition, node.update, node.body].filter((value): value is NonNullable<typeof value> => value !== null);
    case 'switch': return [node.condition, ...node.clauses];
    case 'return': case 'expression_statement': return node.value ? [node.value] : [];
    case 'assignment': case 'binary': return [node.left, node.right];
    case 'conditional': return [node.condition, node.yes, node.no];
    case 'unary': return [node.operand];
    case 'parenthesized': return [node.inner];
    case 'call': return [node.target, node.argumentsList];
    case 'index': return [node.target, node.value];
    case 'member': return [node.target];
    default: return [];
  }
}

import type { Doc, Frame, Profile, Mode } from './types.ts';

export function fits(remaining: number, first: Frame, stack: Frame[]): boolean {
  if (remaining < 0) return false;
  const work = stack.slice(); work.push(first);
  while (work.length) {
    const { indent, mode, document } = work.pop()!;
    switch (document.kind) {
      case 'text': remaining -= document.value.length; break;
      case 'if_break': remaining -= (mode === 'break' ? document.broken : document.flat).length; break;
      case 'line': if (mode === 'break') return true; remaining--; break;
      case 'softline': if (mode === 'break') return true; break;
      case 'hardline': return true;
      case 'concat':
        for (let i = document.parts.length - 1; i >= 0; i--) work.push({ indent, mode, document: document.parts[i] });
        break;
      case 'group': work.push({ indent, mode: document.forced ? 'break' : mode, document: document.child }); break;
      case 'nest': case 'align': work.push({ indent, mode, document: document.child }); break;
    }
    if (remaining < 0) return false;
  }
  return true;
}

export function layout(document: Doc, profile: Profile): string[] {
  const lines: string[] = [], pending: string[] = [];
  const stack: Frame[] = [{ indent: 0, mode: 'break', document }];
  let current = '', column = 0;
  const append = (value: string): void => { current += value; column += value.length; };
  const finalize = (): void => {
    let value = current.replace(/ +$/, '');
    if (pending.length) {
      const comments = pending.join(' '), target = profile.comment_column - 1;
      value += profile.comment_column > 0 && value.length < target && target + comments.length <= profile.width
        ? ' '.repeat(target - value.length) + comments : ' ' + comments;
      pending.length = 0;
    }
    lines.push(value);
  };
  while (stack.length) {
    const { indent, mode, document: node } = stack.pop()!;
    const newline = (): void => { finalize(); current = ' '.repeat(indent); column = indent; };
    switch (node.kind) {
      case 'text': append(node.value); break;
      case 'if_break': append(mode === 'break' ? node.broken : node.flat); break;
      case 'line': if (mode === 'flat') append(' '); else newline(); break;
      case 'softline': if (mode === 'break') newline(); break;
      case 'hardline': newline(); break;
      case 'concat':
        for (let i = node.parts.length - 1; i >= 0; i--) stack.push({ indent, mode, document: node.parts[i] });
        break;
      case 'nest': stack.push({ indent: indent + node.indent, mode, document: node.child }); break;
      case 'align': stack.push({ indent: column, mode, document: node.child }); break;
      case 'suffix': pending.push(node.value); break;
      case 'group': {
        let chosen: Mode | 'forced';
        if (mode === 'flat') chosen = 'flat';
        else if (node.forced) chosen = 'forced';
        else chosen = fits(profile.width - column, { indent, mode: 'flat', document: node.child }, stack) ? 'flat' : 'break';
        node.mode = chosen;
        stack.push({ indent, mode: chosen === 'flat' ? 'flat' : 'break', document: node.child }); break;
      }
    }
  }
  finalize(); return lines;
}

import type { Doc } from './types.ts';

export function documentLines(document: Doc): string[] {
  const lines: string[] = [];
  const visit = (node: Doc, depth: number): void => {
    const indent = ' '.repeat(2 * depth);
    switch (node.kind) {
      case 'text': lines.push(indent + 'text "' + node.value + '"'); break;
      case 'suffix': lines.push(indent + 'suffix "' + node.value + '"'); break;
      case 'if_break': lines.push(indent + 'if_break "' + node.broken + '" "' + node.flat + '"'); break;
      case 'concat': node.parts.forEach(part => visit(part, depth)); break;
      case 'group': lines.push(indent + 'group ' + node.mode); visit(node.child, depth + 1); break;
      case 'nest': lines.push(indent + 'nest ' + node.indent); visit(node.child, depth + 1); break;
      case 'align': lines.push(indent + 'align'); visit(node.child, depth + 1); break;
      default: lines.push(indent + node.kind);
    }
  };
  visit(document, 0); return lines;
}

export function diff(original: string[], formatted: string[]): string[] {
  const n = original.length, m = formatted.length, lcs = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) {
    lcs[i][j] = original[i] === formatted[j] ? lcs[i + 1][j + 1] + 1 : Math.max(lcs[i + 1][j], lcs[i][j + 1]);
  }
  const hunks: {i:number; j:number; deleted:number; inserted:number; lines:string[]}[] = [];
  let i = 0, j = 0, current: {i:number; j:number; deleted:number; inserted:number; lines:string[]} | null = null, deleted = 0, inserted = 0;
  while (i < n || j < m) {
    if (i < n && j < m && original[i] === formatted[j]) { current = null; i++; j++; continue; }
    if (current === null) { current = { i, j, deleted: 0, inserted: 0, lines: [] }; hunks.push(current); }
    if (j === m || (i < n && lcs[i + 1][j] >= lcs[i][j + 1])) {
      current.lines.push('-' + original[i++]); current.deleted++; deleted++;
    } else { current.lines.push('+' + formatted[j++]); current.inserted++; inserted++; }
  }
  const lines = [`hunks=${hunks.length} deleted=${deleted} inserted=${inserted}`];
  for (const hunk of hunks) {
    const startA = hunk.i + (hunk.deleted > 0 ? 1 : 0), startB = hunk.j + (hunk.inserted > 0 ? 1 : 0);
    lines.push(`@@ -${startA},${hunk.deleted} +${startB},${hunk.inserted} @@`, ...hunk.lines);
  }
  return lines;
}

export interface Token {
  kind: string;
  value: string;
  line: number;
  column: number;
  blank: number;
  comment?: boolean;
  index: number;
  leading: Token[];
  trailing: Token[];
  own?: boolean;
  sourceTrailing?: boolean;
}

export interface Lexed {tokens: Token[]; comments: Token[]; records: Token[]}
export interface Profile {
  width: number;
  indent: number;
  brace_style: string;
  space_around_operators: string;
  space_after_keyword: string;
  indent_case_labels: string;
  add_braces: string;
  max_blank_lines: number;
  remove_parens: string;
